export type AdminExtraKey = `adminExtra.${keyof typeof messages}`;
function catalog(column: number): Record<AdminExtraKey, string> {
  return Object.fromEntries(Object.entries(messages).map(([key, values]) => [`adminExtra.${key}`, values[column]])) as Record<AdminExtraKey, string>;
}

